from fastapi import FastAPI
from typing import Dict

# FastAPIアプリケーションを作成
app = FastAPI(title="My First API", version="1.0.0")

# ルートエンドポイント
@app.get("/")
def root() -> Dict[str, str]:
    return {"message": "Welcome to my API!", "version": "1.0.0"}

# ユーザー情報取得API
@app.get("/users/{user_id}")
def get_user(user_id: int) -> Dict:
    # 実際はデータベースから取得
    return {
        "user_id": user_id,
        "name": f"User {user_id}",
        "email": f"user{user_id}@example.com"
    }

# 商品一覧API
@app.get("/products")
def list_products() -> Dict:
    return {
        "products": [
            {"id": 1, "name": "Laptop", "price": 1200},
            {"id": 2, "name": "Mouse", "price": 25},
            {"id": 3, "name": "Keyboard", "price": 75}
        ]
    }

if __name__ == "__main__":
    print("FastAPI app structure created!")
    print("\nEndpoints:")
    print("  GET  /           - Root endpoint")
    print("  GET  /users/{id} - Get user by ID")
    print("  GET  /products   - List all products")
    print("\n📝 Note: 実際は uvicorn main:app --reload で起動")
    print("📝 http://localhost:8000/docs で自動ドキュメント閲覧可能")

