from fastapi import FastAPI, HTTPException
from pydantic import BaseModel
from typing import List, Dict, Optional

app = FastAPI(title="Task Management API")

class TaskCreate(BaseModel):
    title: str
    description: str
    completed: bool = False

class TaskResponse(BaseModel):
    id: int
    title: str
    description: str
    completed: bool

# インメモリデータベース
tasks_db: Dict[int, TaskResponse] = {}
next_id = 1

# CREATE
@app.post("/tasks", response_model=TaskResponse, status_code=201)
def create_task(task: TaskCreate) -> TaskResponse:
    global next_id
    new_task = TaskResponse(id=next_id, **task.dict())
    tasks_db[next_id] = new_task
    next_id += 1
    return new_task

# READ (All)
@app.get("/tasks", response_model=List[TaskResponse])
def list_tasks() -> List[TaskResponse]:
    return list(tasks_db.values())

# READ (One)
@app.get("/tasks/{task_id}", response_model=TaskResponse)
def get_task(task_id: int) -> TaskResponse:
    if task_id not in tasks_db:
        raise HTTPException(status_code=404, detail="Task not found")
    return tasks_db[task_id]

# UPDATE
@app.put("/tasks/{task_id}", response_model=TaskResponse)
def update_task(task_id: int, task: TaskCreate) -> TaskResponse:
    if task_id not in tasks_db:
        raise HTTPException(status_code=404, detail="Task not found")

    updated_task = TaskResponse(id=task_id, **task.dict())
    tasks_db[task_id] = updated_task
    return updated_task

# DELETE
@app.delete("/tasks/{task_id}")
def delete_task(task_id: int) -> Dict[str, str]:
    if task_id not in tasks_db:
        raise HTTPException(status_code=404, detail="Task not found")

    del tasks_db[task_id]
    return {"message": "Task deleted successfully"}

if __name__ == "__main__":
    print("✅ Complete CRUD API created!")
    print("\n📋 Endpoints:")
    print("  POST   /tasks     - Create task")
    print("  GET    /tasks     - List all tasks")
    print("  GET    /tasks/{id} - Get specific task")
    print("  PUT    /tasks/{id} - Update task")
    print("  DELETE /tasks/{id} - Delete task")
    print("\n📝 Note: HTTPExceptionで適切なエラーハンドリング")
    print("📝 status_codeでHTTPステータスを制御")
